"""Stage AYS metadata for review. Does not publish or alter checkout settings."""
from datetime import datetime, timezone
import json
import os
import re
import tempfile
from uuid import uuid4

from check_catalog import application_ids
from probe import PROJECT, browser_settings, configured_origin, wait_for_ays

READ = r"""
const origin = arguments[0], appId = arguments[1];
const done = arguments[arguments.length - 1];
(async () => {
  if (location.origin !== origin) return {error: "ORIGIN"};
  if (typeof window.g_ck !== "string" || !window.g_ck) return {error: "SESSION"};
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 15000);
  try {
    const query = new URLSearchParams({
      sysparm_query: "u_app_id=" + appId,
      sysparm_fields: "sys_id,u_app_id,name,support_group,support_group.name,support_group.email",
      sysparm_limit: "2", sysparm_display_value: "all"
    });
    const response = await fetch("/api/now/table/cmdb_ci_business_app?" + query, {
      method: "GET", credentials: "same-origin", redirect: "error", cache: "no-store",
      signal: controller.signal,
      headers: {Accept: "application/json", "X-UserToken": window.g_ck}
    });
    if (!response.ok) return {error: "HTTP", http: response.status};
    const body = await response.json();
    if (!Array.isArray(body.result)) return {error: "SHAPE"};
    if (body.result.length !== 1) return {error: "RECORD_COUNT"};
    const r = body.result[0];
    const value = item => item && typeof item === "object" ? item.value : item;
    return {record: {
      app_id: value(r.u_app_id), source_sys_id: value(r.sys_id), official_name: value(r.name),
      support_group: {sys_id: value(r.support_group), name: value(r["support_group.name"]),
                      email: value(r["support_group.email"])}
    }};
  } catch {
    return {error: controller.signal.aborted ? "TIMEOUT" : "RESPONSE"};
  } finally { clearTimeout(timer); }
})().then(done, () => done({error: "RESPONSE"}));
"""


def clean_text(value, limit):
    if not isinstance(value, str) or not value.strip() or len(value) > limit:
        raise ValueError("Invalid metadata text")
    if any(ord(c) < 32 or ord(c) == 127 for c in value):
        raise ValueError("Control character in metadata")
    return value.strip()


def sys_id(value):
    if not isinstance(value, str) or not re.fullmatch(r"[0-9a-fA-F]{32}", value):
        raise ValueError("Invalid source identity")
    return value.lower()


def validate_record(raw, expected):
    if not isinstance(raw, dict) or raw.get("app_id") != expected:
        raise ValueError("Unexpected application")
    group = raw.get("support_group")
    if not isinstance(group, dict):
        raise ValueError("Missing support group")
    return {
        "app_id": expected,
        "source_sys_id": sys_id(raw.get("source_sys_id")),
        "official_name": clean_text(raw.get("official_name"), 1000),
        "support_group": {
            "sys_id": sys_id(group.get("sys_id")),
            "name": clean_text(group.get("name"), 1000),
            # Source metadata only. This does not authorize an email recipient.
            "email": clean_text(group.get("email"), 1000),
        },
    }


def validate_records(records, expected):
    if not expected or len(set(expected)) != len(expected) or len(records) != len(expected):
        raise ValueError("Incomplete inventory")
    if any(not re.fullmatch(r"APP[0-9]{8}", item) for item in expected):
        raise ValueError("Invalid configured ID")
    by_id = {}
    identities = set()
    groups = {}
    for record in records:
        item = validate_record(record, record.get("app_id")) if isinstance(record, dict) else None
        if item is None or item["app_id"] not in expected or item["app_id"] in by_id:
            raise ValueError("Unexpected or duplicate application")
        if item["source_sys_id"] in identities:
            raise ValueError("Duplicate source identity")
        group = item["support_group"]
        if group["sys_id"] in groups and groups[group["sys_id"]] != group:
            raise ValueError("Inconsistent support group metadata")
        groups[group["sys_id"]] = group
        identities.add(item["source_sys_id"])
        by_id[item["app_id"]] = item
    if set(by_id) != set(expected):
        raise ValueError("Missing applications")
    return [by_id[key] for key in sorted(by_id)]


def save_candidate(project, origin, records, expected):
    records = validate_records(records, expected)
    now = datetime.now(timezone.utc)
    payload = {
        "schema_version": 1, "review_status": "unreviewed", "fetched_at_utc": now.isoformat(),
        "source": {"system": "ServiceNow", "origin": origin, "table": "cmdb_ci_business_app"},
        "scope": {"kind": "configured_app_ids", "expected_ids": sorted(expected)},
        "applications": records,
    }
    folder = project / "local" / "ays"
    folder.mkdir(parents=True, exist_ok=True)
    destination = folder / ("candidate-" + now.strftime("%Y%m%dT%H%M%S") + "-" + uuid4().hex + ".json")
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", dir=folder,
                                         prefix=".pending-", suffix=".tmp", delete=False) as stream:
            temporary = stream.name
            json.dump(payload, stream, indent=2, ensure_ascii=False, allow_nan=False)
            stream.write("\n")
            stream.flush()
            os.fsync(stream.fileno())
        # Unique candidate names preserve all earlier review copies.
        os.replace(temporary, destination)
        temporary = None
    finally:
        if temporary is not None:
            os.unlink(temporary)
    return destination


def main():
    driver = None
    phase = "settings"
    try:
        settings = browser_settings(PROJECT)
        origin = configured_origin()
        phase = "application IDs"
        ids = application_ids(PROJECT)
        from app_health_checker.browser.edge import create_edge
        phase = "browser launch"
        driver = create_edge(settings)
        driver.set_page_load_timeout(60)
        driver.set_script_timeout(25)
        phase = "open AYS"
        driver.get(origin + "/")
        phase = "AYS sign-in readiness"
        wait_for_ays(driver, origin)
        records = []
        for index, app_id in enumerate(ids, 1):
            phase = "metadata read " + app_id
            result = driver.execute_async_script(READ, origin, app_id)
            if not isinstance(result, dict) or "error" in result:
                raise ValueError("Read failed")
            phase = "metadata validation " + app_id
            records.append(validate_record(result.get("record"), app_id))
            print(f"READ: {index}/{len(ids)}", flush=True)
        phase = "candidate validation and save"
        destination = save_candidate(PROJECT, origin, records, ids)
        print("APPS SAVED:", len(records))
        print("CANDIDATE:", destination.name)
        print("EXPORT: PASS; review copy saved in local/ays")
    except KeyboardInterrupt:
        print("EXPORT: CANCELLED")
        return 1
    except Exception:
        print("EXPORT: STOPPED; phase=" + phase)
        return 1
    finally:
        if driver is not None:
            try:
                driver.quit()
            except Exception:
                print("BROWSER: Close the export window manually")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
